INSERT INTO tasks VALUES('t-docker-validate','p-gtte',NULL,0,'Validate: Docker-as-OS image builds + runs end-to-end','CRITICAL: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db before any plandb. Run ''docker compose build'' + ''docker compose up -d'', wait for healthy, exercise the API (POST /intent, GET /brief, POST /approve, POST /verify), report image size and boot time, collect logs. Fix any issues that surface (missing deps in Dockerfile, model download failure, wrong paths). Make a PR if fixes needed; otherwise just report. Branch: fix/docker-validate if fixes needed.','done','shell',10,'docker-validator','2026-04-21 22:20:44','2026-04-21 22:20:44','2026-04-21 22:28:09','{"api_ok":true,"boot_s":7,"build_s":200,"image_gb":4.35,"mem_mb":3.1,"notes":"4 bugs fixed: placeholder SHA256, Rust 1.82 (too old for edition2024), chief-core 127.0.0.1 default bind, no static file server on 5173. Plus IPv6 port-mapping workaround and version:3.8 cleanup.","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/25"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 22:20:44',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:19:32','2026-04-21 22:28:09');
INSERT INTO tasks VALUES('t-mb-tauri','p-gtte',NULL,0,'Integration: Tauri-wrap Morning Brief (native desktop binary)','CRITICAL: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db before any plandb. Worktree: labs/chief-os-tauri. Wrap prototypes/morning-brief in Tauri v2 so it ships as a native desktop binary. Per docs/brand/visual-language.md — non-negotiable design rules. Create ONLY files under prototypes/morning-brief/src-tauri/ (scaffold via tauri init) + tauri.conf.json + update prototypes/morning-brief/package.json with tauri scripts. Do NOT modify prototypes/morning-brief/src/ — that''s another agent''s work (mb-live-api). Bundle fonts in binary at build time (Inter from rsms.me/inter or SIL OFL Inter tarball), drop into src-tauri/fonts/. Register keyboard shortcuts via tauri-plugin-global-shortcut (⌘ Space / Ctrl+Space for Omnibar placeholder, ⌘ . for HAX Inbox placeholder, Esc to reset focus). Native window config: fullscreen flag on release, 1280x800 in dev, titleBarStyle=overlay on mac, decorations=false on Linux kiosk build. Install tauri-plugin-context-menu, tauri-plugin-window-vibrancy. Add build target: ''npm run tauri build'' produces a .app bundle on mac, .AppImage+.deb on Linux. Add a README section ''Running as native app''. Acceptance: npm run tauri dev opens a native window displaying Morning Brief; window is fullscreen in prod; no browser chrome visible; font is bundled (verify via devtools); ⌘+Space logs a ''TODO'' to console (real surface comes later); cargo build of the src-tauri Rust code succeeds; npm run tauri build produces a platform-native bundle. Worktree: branch int/mb-tauri. References: docs/brand/visual-language.md (ESPECIALLY sections 1, 2, 3, 7, 8, 9, 15, 16).','done','code',9,'codex-mb-tauri','2026-04-21 22:21:38','2026-04-21 22:21:38','2026-04-21 22:34:17','{"cargo_build_ok":true,"fonts_bundled":true,"global_shortcuts":2,"npm_tauri_scripts":true,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/27","scaffold_created":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 22:21:38',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:19:32','2026-04-21 22:34:17');
INSERT INTO tasks VALUES('t-mb-live-api','p-gtte',NULL,0,'Integration: Morning Brief wired to chief-core HTTP API','CRITICAL: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db before any plandb. Worktree: labs/chief-os-mb-api. Only modify files under prototypes/morning-brief/src/ + vite.config.ts + package.json deps. Do NOT touch prototypes/morning-brief/src-tauri/ — that''s another agent''s work (mb-tauri). Add src/api.ts: typed fetch wrapper around chief-core''s 6 routes. Add src/hooks/useBriefState.ts: polls /brief every 3s (SSE later); returns BriefState or loading/error. Modify MorningBrief.tsx to useBriefState() instead of loading mock/brief-state.json directly. Wire NeedsYouCard Review button → POST /approve (ceremony: false for tier-1, true for tier-3). Wire Rewind slider → POST /rewind with duration. Wire CeremonyModal Confirm → POST /approve with ceremony:true. Env: VITE_CHIEF_CORE_URL (default http://127.0.0.1:4711). Fallback behaviour: if /status fails, fall back to mock/brief-state.json with a visible banner at top ''demo mode (no chief-core running)''. Write vitest tests for api.ts and useBriefState with mocked fetch. Keep existing UI look-and-feel; do not redesign. Acceptance: with chief-core running locally, Morning Brief shows live cards generated from POST /intent calls; without, demo-mode banner shows. Approval button actually ships and returns attestation id. Rewind actually reverts state. npm run build clean. Worktree: branch int/mb-live-api.','done','code',9,'codex-mb-live','2026-04-21 22:22:23','2026-04-21 22:22:23','2026-04-21 22:28:24','{"api_functions":6,"coverage":"api.ts+useBriefState.ts 80%+ target","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/26","tests_passing":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 22:22:23',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:19:32','2026-04-21 22:28:24');
INSERT INTO tasks VALUES('t-w4-sdk','p-gtte',NULL,0,'Wave 4: chief-sdk Rust + TS + hello-world pack','Build crates/chief-sdk (Rust) + packages/chief-sdk-ts (TypeScript) + prototypes/hello-world-pack (reference dogfood pack). Branch int/sdk-crate. Full spec in GH issue. Follows adr/0010 + docs/16 + docs/17. No touch outside scope.','done','code',9,'codex-oauth','2026-04-21 22:48:50','2026-04-21 22:48:50','2026-04-21 23:42:24','{"commit":"63d589a","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/31","summary":"chief-sdk v0.1.0 + chief-sdk-ts + hello-world-pack merged"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 22:48:50',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:45:03','2026-04-21 23:42:24');
INSERT INTO tasks VALUES('t-w4-broker','p-gtte',NULL,0,'Wave 4: Capability Broker real enforcement in chief-core','Replace allow-all stub in crates/chief-core/src/state.rs with real Capability Broker enforcement. Deny on missing or un-scoped grants. Branch int/broker-enforce. Full spec in GH issue. Scope: crates/chief-core/** only.','done','code',9,'default','2026-04-21 23:06:45','2026-04-21 23:06:45','2026-04-21 23:42:24','{"commit":"f321c88","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/32","summary":"CapabilityBroker enforcement merged, 9 broker_enforce tests pass"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 23:06:45',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:45:03','2026-04-21 23:42:24');
INSERT INTO tasks VALUES('t-w4-oauth','p-gtte',NULL,0,'Wave 4: OAuth session broker (crates/chief-oauth)','New crate crates/chief-oauth implementing the ''broker holds tokens, pack gets SessionHandle'' pattern from docs/17 Layer 1. OS-owned token storage, scoped request signing. Branch int/oauth-broker. Full spec in GH issue. Scope: crates/chief-oauth/** + root Cargo.toml (add member) only.','done','code',9,NULL,'2026-04-21 23:06:45','2026-04-21 23:06:45','2026-04-21 23:06:45','{"next":"Review & push PR","pr_notes":"Created crates/chief-oauth with OAuthBroker, sealed token storage (XChaCha20-Poly1305), and scope enforcement. Tests: flow_lifecycle, scope_enforcement, token_never_leaks, revoke, real_google. Branch: int/oauth-broker, commit: 942152f.","providers":["google","github","custom"],"sealed_at_rest":true,"tests_mock":5}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:45:03','2026-04-21 23:06:45');
INSERT INTO tasks VALUES('t-njcl','p-gtte',NULL,0,'OAuth broker crate: finish storage.rs rewrite + add to workspace',unistr('Rescue OAuth work left by codex in broken state (see t-w4-oauth).\u000aWorktree: ../chief-os-oauth (branch int/oauth-broker, commit 942152f + uncommitted storage.rs rewrite).\u000aTasks:\u000a1. Finish storage.rs rewrite — reconcile StoredSession vs TokenRecord types.\u000a2. Add crates/chief-oauth to root Cargo.toml workspace members.\u000a3. cargo build -p chief-oauth clean.\u000a4. cargo test -p chief-oauth passes.\u000a5. cargo clippy -p chief-oauth -- -D warnings clean.\u000a6. PR + merge. Not blocking Wave 5 (HN briefer needs no OAuth).\u000aScope: crates/chief-oauth/** + root Cargo.toml.'),'done','code',8,NULL,'2026-04-21 23:55:12','2026-04-21 23:55:12','2026-04-21 23:55:12','{"commit":"7d117af","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/33","summary":"OAuth crate rescued — 18 tests pass, clippy/fmt clean, workspace build green. Follow-up: wire into chief-core (new task)"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:42:33','2026-04-21 23:55:12');
INSERT INTO tasks VALUES('t-w5-ui','p-gtte',NULL,0,'Wave 5: build chief-ui v0 component kit (React + Rust)',unistr('Build the chief-ui primitive library per ADR-0011 and docs/18-ui-standardization.md.\u000aDeliverables:\u000a1. packages/chief-ui-ts/ (React, TypeScript). Primitives v0: Pane, Row, Badge (closed variants: needs-you/review/handled/ceremony/anchor), SourceAvatar (closed 8-hue palette), SectionHeader, TabBar, CommandPill, Widget, DotTrail, Sparkline, HoldRing.\u000a2. crates/chief-ui/ (Rust companion crate for prop types mirror — used by Rust-based Pack SDK).\u000a3. Design tokens: src/tokens.css + src/tokens.rs. Colors, typography, spacing, radius, motion presets — values from docs/brand/visual-language.md §4-7.\u000a4. Internal scaffolding: copy Shadcn source (MIT) into packages/chief-ui-ts/internal/ and re-theme heavily. Do NOT re-export Shadcn or Radix from the public entry.\u000a5. Tauri v2 integration: window-vibrancy plugin wired for macOS liquid glass material. Fallback CSS blur on Linux.\u000a6. Public entry: packages/chief-ui-ts/src/index.ts exports ONLY primitives above.\u000a7. Visual tests: Storybook or equivalent, stories matching screenshots/01-desktop-hero.png composition.\u000a8. cargo test -p chief-ui + npm test in packages/chief-ui-ts pass.\u000a9. README with 30-line example of composing the Brief from primitives.\u000a\u000aScope: packages/chief-ui-ts/** + crates/chief-ui/** + root Cargo.toml member add.\u000aDo NOT touch chief-sdk (consumer crate). Do NOT touch chief-core.\u000a\u000aReference: screenshots/01-desktop-hero.png shows the target composition.'),'done','code',10,'codex-chief-ui','2026-04-21 23:45:04','2026-04-22 00:07:35','2026-04-22 00:07:35','{"builds_verified":true,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/34","primitives":17,"tests_passed":7}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 23:45:04',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:43:15','2026-04-22 00:07:35');
INSERT INTO tasks VALUES('t-w5-hn-brief','p-gtte',NULL,0,'Wave 5a: HN / Substack briefer pack (first dogfood)',unistr('Build the first dogfood pack: HN / Substack Briefer.\u000aPurpose: every morning, fetch Hacker News top stories and user''s subscribed Substack feed, filter/score via on-device LLM, write top 3-5 as memory nodes with region-routed briefs, render one card in the Brief list.\u000a\u000aGrants declared in pack manifest:\u000a- net.http { hosts: [''news.ycombinator.com'',''hn.algolia.com''] } (usage_reason: ''fetch HN top-stories feed'')\u000a- net.http { hosts: [''*.substack.com''] } (usage_reason: ''fetch user Substack feed'')\u000a- mem.write { types: [''thought'',''card''] } (usage_reason: ''persist briefed items to Memory Graph'')\u000a- surface.pane { surfaces: [''morning-brief''] } (usage_reason: ''render daily HN + Substack card in Brief'')\u000a- llm.generate { max_tokens: 500 } (usage_reason: ''summarize + score stories'')\u000a\u000aImplementation:\u000a1. prototypes/hn-briefer/ (Rust pack using @chief-os/sdk + chief-ui Rust crate via SDK).\u000a2. Single Agent that on morning trigger: fetches → scores → writes → renders card.\u000a3. Render card in Brief using chief-ui <Row> primitive (not custom HTML).\u000a4. Tests using SDK InMemoryConnector stubs.\u000a\u000aAcceptance:\u000a- cargo build -p hn-briefer clean.\u000a- cargo test -p hn-briefer passes (unit + integration with stubs).\u000a- Manifest static import scan — pack uses only @chief-os/sdk and @chief-os/ui; no other imports.\u000a- cargo clippy clean.\u000a- README with example card shape.\u000a\u000aScope: prototypes/hn-briefer/** + root Cargo.toml workspace member add.\u000aDo NOT touch chief-sdk, chief-ui, chief-core.'),'failed','code',9,'codex-chief-ui','2026-04-22 00:07:35','2026-04-22 00:07:35','2026-04-22 00:15:28',NULL,'Previous codex-chief-ui agent auto-claimed via ''done --next'' but then exited without doing work. Releasing for fresh dispatch with updated brief (chief-ui v0 now shipped).',NULL,NULL,0,1,'exponential',1000,NULL,30,'2026-04-22 00:07:35',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:43:15','2026-04-22 00:15:28');
INSERT INTO tasks VALUES('t-w5b-oauth-wire','p-gtte',NULL,0,'OAuth: wire chief-oauth into chief-core via CapabilityBroker',unistr('Wire the now-working chief-oauth crate into chief-core so packs can request OAuth grants via the standard CapabilityBroker flow.\u000aBlocked by: chief-sdk already landed. Needs chief-core to import chief-oauth and expose session-based capability grants.\u000aSteps:\u000a1. Add chief-oauth dep to crates/chief-core/Cargo.toml.\u000a2. In chief-core/state.rs: hold Arc<OAuthBroker> alongside CapabilityBroker.\u000a3. New route POST /oauth/start — pack invokes with provider + scopes + redirect_uri. Returns AuthorizationChallenge (auth_url, state, flow_id).\u000a4. New route POST /oauth/complete — OS presents the code back. Returns SessionHandle.\u000a5. Agent SDK capability ctx.oauth.start(...) / ctx.oauth.complete(...) adapters.\u000a6. Agent SDK ctx.net().proxy(session, request) — routes through OAuthBroker.proxy_request.\u000a7. Broker.check() gains OAuth-specific logic: when net.http.oauth2 is requested, check if session scopes cover the request.\u000a8. Tests: end-to-end integration with mock OAuth server; verify bearer token never appears in any pack-visible type or log.\u000a\u000aNot blocking Wave 5a (HN briefer). Needed before Gmail triage and Calendar packs (Wave 5b+).\u000a\u000aScope: crates/chief-core/**. Do NOT modify chief-oauth or chief-sdk.'),'done','code',6,'codex-oauth-wire','2026-04-22 02:09:43','2026-04-22 02:09:46','2026-04-22 02:20:36','{"files_modified":6,"gap":"none","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/43","routes":["start","complete","proxy"],"tests":6}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:09:46',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:55:12','2026-04-22 02:20:36');
INSERT INTO tasks VALUES('t-w5-hn-brief2','p-gtte',NULL,0,'Wave 5a: HN / Substack briefer pack (first dogfood, uses chief-ui v0)',unistr('FIRST DOGFOOD PACK — validates the public SDK + UI kit by consuming only their exported surface.\u000a\u000aPurpose: every morning, fetch Hacker News top stories and the user''s subscribed Substack feed, filter/score via on-device LLM, persist top 3-5 as memory nodes, render one brief card in the Brief list.\u000a\u000aPlanDB:\u000a- ID: t-w5-hn-brief2\u000a- Branch: int/hn-briefer (worktree ../chief-os-w5-hn-brief already created from main 9cbc534)\u000a- PlanDB db: pin: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db\u000a- Agent name suggestion: PLANDB_AGENT=codex-hn-brief\u000a\u000aStrict file scope (parallel-safety):\u000a  ONLY modify:\u000a  - prototypes/hn-briefer/** (new)\u000a  - Root Cargo.toml — add prototypes/hn-briefer to workspace members. Do NOT touch other members.\u000a  NEVER touch:\u000a  - crates/chief-sdk/**, crates/chief-ui/**, crates/chief-core/**, crates/chief-oauth/**\u000a  - packages/chief-sdk-ts/**, packages/chief-ui-ts/**\u000a  - prototypes/hello-world-pack/**, prototypes/morning-brief/** etc.\u000a  - Any doc, ADR, or legal/brand file.\u000a\u000aPublic API discipline (ADR-0011 + ADR-0010):\u000a- Consume ONLY @chief-os/sdk and @chief-os/ui public exports.\u000a- UI composition uses <Row>, <Badge variant=''handled''|''review''|''needs-you''>, <SourceAvatar color=''amber''|''blue''|...>, <Pane>, <SectionHeader>. NO raw HTML/CSS for UI chrome.\u000a- Rust pack uses chief-sdk Pack/Agent/CapabilityContext only. No direct chief-core imports. No chief-ui Rust crate import needed (pack emits Card data; rendering happens in the Brief consumer).\u000a\u000aGrants declared in pack manifest (manifest.toml):\u000a- net.http { hosts: [''news.ycombinator.com'',''hn.algolia.com''] } — usage_reason: ''fetch HN top-stories feed''\u000a- net.http { hosts: [''*.substack.com''] } — usage_reason: ''fetch user Substack feeds''\u000a- mem.write { types: [''thought'',''card''] } — usage_reason: ''persist briefed items to Memory Graph''\u000a- surface.pane { surfaces: [''morning-brief''] } — usage_reason: ''render daily HN + Substack card in Brief''\u000a- llm.generate { max_tokens: 500 } — usage_reason: ''summarize + score stories''\u000a\u000aImplementation (Rust only at v0 — Card rendering is data, not React):\u000a1. prototypes/hn-briefer/Cargo.toml — depends on chief-sdk (workspace member), serde, reqwest, tokio.\u000a2. src/lib.rs — impl Pack + one Agent that on morning trigger: fetch HN top (10) via ctx.net().http(), score via ctx.llm().generate() with a compact prompt, pick top 5, write each as mem://thought/hn-<id> + one aggregate mem://card/hn-briefer-daily via ctx.memory().write(), emit a Card matching the chief-ui <Row> contract (sender=''HN Briefer'', subject, snippet, badge=''handled'', timestamp=now, source_color=''amber'').\u000a3. manifest.toml — the 5 grants above, with usage_reason on each.\u000a4. tests/integration.rs — full smoke using SDK InMemoryConnector stubs: inject mock HTTP responses, run the agent, assert memory nodes written + Card emitted with the correct badge variant.\u000a5. README.md — 20-line README with example card JSON + install instructions (Nix-flake placeholder fine; real flake integration follow-up).\u000a\u000aAcceptance (hard gates):\u000a- cargo build -p hn-briefer — clean.\u000a- cargo test -p hn-briefer — integration test passes.\u000a- cargo clippy -p hn-briefer --all-targets -- -D warnings — clean.\u000a- cargo fmt --check — clean.\u000a- Static import check: grep -r ''use chief_core\\|use chief_ui\\|use chief_oauth'' prototypes/hn-briefer/src/ returns nothing (pack only imports chief-sdk, stdlib, and well-known utility crates: serde, reqwest, tokio, anyhow).\u000a- Manifest declares all 5 grants with usage_reason populated. No empty usage_reason strings.\u000a- Card emission uses Badge::Handled (from chief-sdk enum, closed set per ADR-0012 + ADR-0011).\u000a\u000aGit + PR workflow:\u000a  export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db\u000a  export PLANDB_AGENT=codex-hn-brief\u000a  cd ../chief-os-w5-hn-brief\u000a  plandb task claim t-w5-hn-brief2 --agent $PLANDB_AGENT\u000a  plandb task start t-w5-hn-brief2 --agent $PLANDB_AGENT\u000a  # ... do the work ...\u000a  git add prototypes/hn-briefer Cargo.toml\u000a  git commit -m ''feat(pack): HN + Substack briefer pack (t-w5-hn-brief2)\\n\\nFirst dogfood consuming only @chief-os/sdk public API.\\nValidates ADR-0010 parity and ADR-0011 import discipline.\\n\\nCo-Authored-By: Codex <noreply@openai.com>''\u000a  git push -u origin int/hn-briefer\u000a  gh pr create --title ''feat(pack): HN + Substack briefer (first dogfood)'' --body ''Closes t-w5-hn-brief2. First pack built entirely against the public @chief-os/sdk surface. Validates the SDK is complete enough to ship a real pack.''\u000a  plandb done --next --agent $PLANDB_AGENT --result ''{"pr":"<url>","grants":5,"cards_emitted_per_day":1}''\u000a\u000aNon-goals:\u000a- Substack feed discovery (user manually configures the Substack URL in a pack setting, stub that via a hardcoded list at v0).\u000a- OAuth (HN + Substack public RSS need no OAuth — explicit design choice).\u000a- Actual LLM routing (use the ctx.llm() stub; real routing is chief-core concern).\u000a- UI rendering in React — Brief consumer renders the Card via chief-ui; pack only emits data.\u000a\u000aReferences:\u000a- docs/16-pack-sdk.md\u000a- docs/18-ui-standardization.md\u000a- adr/0010-sdk-public-api-stability.md\u000a- adr/0011-ui-stack-and-component-library.md\u000a- prototypes/hello-world-pack/ (reference for manifest + Pack trait pattern)\u000a\u000aCloses when merged.'),'done','code',9,'codex-hn-brief','2026-04-22 00:16:01','2026-04-22 00:16:03','2026-04-22 00:20:01','{"badge":"handled","grants":5,"items_per_day":5,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/35","sdk_gaps":0}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 00:16:03',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:15:28','2026-04-22 00:20:01');
INSERT INTO tasks VALUES('t-w6-sdk-runtime','p-gtte',NULL,0,'Agent Runtime Phase 1: extend chief-sdk with AiBuilder + HarnessBuilder + ToolHandle (v0.2)',unistr('Implement ADR-0013 Phase 1 in chief-sdk.\u000aReference: adr/0013-agent-runtime-two-tier-llm.md, docs/20-agent-runtime.md.\u000a\u000aDeliverables:\u000a1. crates/chief-sdk: add Tier enum (Fast, Deep, closed), AiBuilder, HarnessBuilder, ToolHandle, HarnessTranscript, HarnessError, AiError per docs/20.\u000a2. Add CapabilityKind::LlmAi + CapabilityKind::LlmHarness to the closed enum.\u000a3. Builders delegate to a trait (RuntimeBackend); ship an InMemoryRuntime stub for unit testing.\u000a4. Deprecation shim: ctx.llm().generate() calls-through to ctx.ai().prompt(...).tier(Fast).call::<String>().\u000a5. chief-sdk-ts: parallel TS bindings for the new types.\u000a6. Version bump to chief-sdk 0.2.0 + chief-sdk-ts 0.2.0.\u000a7. Tests: builder API, tier enum closed-ness, AiError/HarnessError variants, tool-handle lifetime.\u000a8. README: updated 30-line example showing ctx.ai() + ctx.harness().\u000a\u000aScope: crates/chief-sdk/**, packages/chief-sdk-ts/**. NEVER touch chief-core, chief-ui, chief-oauth, prototypes/**.\u000aAcceptance: cargo build, cargo test -p chief-sdk, cargo clippy -- -D warnings, cargo fmt --check all clean.\u000aHN briefer migration is a separate follow-up task (not in this PR scope).'),'done','code',10,'codex-sdk-runtime','2026-04-22 00:31:50','2026-04-22 00:31:51','2026-04-22 00:42:44','{"build_status":"clean","clippy_status":"clean","hn_briefer_status":"9 passed - deprecation shim working","new_tests":17,"new_types":7,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/36","sdk_version":"0.2.0","test_status":"17 passed"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 00:31:51',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:27:18','2026-04-22 00:42:44');
INSERT INTO tasks VALUES('t-w6-router','p-gtte',NULL,0,'Agent Runtime Phase 2: model router + Controls -> Models UI',unistr('Implement ADR-0013 Phase 2. Reference: docs/20-agent-runtime.md §Model router, §Controls -> Models sub-surface.\u000a\u000aDeliverables:\u000a1. crates/chief-core: ModelRouter reads $CHIEF_HOME/models.toml, picks model by tier + constraints + consequentiality + local availability.\u000a2. models.toml schema: [tiers.fast] / [tiers.deep] / [providers.anthropic] / [providers.openai] / [defaults].\u000a3. Install-time check: when a pack manifest declares tier=X, verify user''s models_config[X] is bound. Unbound -> block with actionable dialog.\u000a4. packages/chief-ui-ts: Models sub-surface (part of Controls), using existing primitives + new Toggle/Select/Picker if not already present.\u000a5. Integration with chief-oauth sealed storage for provider API keys.\u000a6. Tests: router picks correct model by tier; OOM fallback to cloud; install-blocks on unbound tier.\u000a\u000aScope: crates/chief-core/**, packages/chief-ui-ts/controls/models/**. Uses (not modifies) chief-oauth for sealed storage.\u000aAcceptance: cargo clippy clean; install-block dialog UX verified against screenshot of chief-ui.\u000aBlocks on: t-w6-sdk-runtime (needs chief-sdk 0.2 types).'),'done','code',8,'codex-model-router','2026-04-22 01:03:02','2026-04-22 01:03:05','2026-04-22 01:13:30','{"new_dependencies_rust":["toml","num_cpus"],"new_primitive":"Select","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/37","router_tests":12,"select_tokens_css_footprint_bytes":2100}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 01:03:05',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:27:18','2026-04-22 01:13:30');
INSERT INTO tasks VALUES('t-w6-harness','p-gtte',NULL,0,'Agent Runtime Phase 3: chief-core harness runtime + opencode adapter (largest v0 build)',unistr('CONSOLIDATED 2026-04-21: t-w6-custom-engine merged into this task. Per ADR-0014, CustomEngine must ship in the same PR as OpencodeEngine so the engine-swap abstraction is proven (parity test: same transcript against both). Deliver BOTH engine impls + the runtime that uses them.\u000a---\u000aImplement ADR-0013 Phase 3 — the actual agent runtime. Reference: docs/20-agent-runtime.md §Harness runtime.\u000a\u000aDeliverables:\u000a1. crates/chief-core: HarnessSessionState, budget/turn/wall enforcement, per-turn attestation emission, transcript assembly, capability-broker check per tool invocation, external-action Ceremony gate.\u000a2. Engine adapter trait (HarnessEngine) + OpencodeEngine impl wrapping opencode. Vendor opencode if needed; do not expose it in chief-sdk surface.\u000a3. Meta-prompt impl with depth cap = 3, tool narrowing, shared budget. Inline (not concurrent) at v0.\u000a4. Event-log integration: SessionBorn, PerTurn, SessionClose, ExternalActionBlocked events all signed.\u000a5. Termination reason enum wired to Provenance Explorer (existing surface).\u000a6. Tests: happy path (.ai single-call + .harness multi-turn with fake engine), budget kill, external-action block, meta-prompt depth enforce, tool-handle invalidation post-run.\u000a\u000aScope: crates/chief-core/**. Vendor opencode under crates/chief-core/engines/opencode/ or similar. NEVER touch chief-sdk, chief-ui, chief-oauth, prototypes/**.\u000aAcceptance: cargo test -p chief-core harness-runtime passes with comprehensive matrix; workspace clippy clean.\u000aBlocks on: t-w6-sdk-runtime + t-w6-router.'),'done','code',8,'codex-harness','2026-04-22 01:20:54','2026-04-22 01:40:28','2026-04-22 01:40:28','{"ai_tests":3,"build_status":"clean","chief_sdk_tests":17,"clippy":"clean","engine_parity":"proven_by_fixture_tests","engines":["opencode","custom"],"format":"clean","harness_tests":13,"hn_briefer_tests":9,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/39"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 01:20:54',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:27:18','2026-04-22 01:40:28');
INSERT INTO tasks VALUES('t-w6-migrate','p-gtte',NULL,0,'Agent Runtime Phase 4: migrate HN briefer to ctx.ai() + remove v0.1 stub',unistr('Migrate prototypes/hn-briefer from ctx.llm().generate() to ctx.ai(). Remove deprecation shim from chief-sdk. Bump chief-sdk to 0.3.0.\u000a\u000aDeliverables:\u000a1. prototypes/hn-briefer/src/lib.rs: replace ctx.llm().generate() with ctx.ai().prompt(...).tier(Fast).call::<String>() per ADR-0013.\u000a2. prototypes/hn-briefer/manifest.toml: add tier=''fast'' to the llm grant.\u000a3. crates/chief-sdk: remove ctx.llm().generate() deprecation shim. Bump to 0.3.0.\u000a4. packages/chief-sdk-ts: parallel cleanup + bump.\u000a5. Tests still pass.\u000a\u000aScope: prototypes/hn-briefer/**, crates/chief-sdk/**, packages/chief-sdk-ts/**.\u000aBlocks on: t-w6-harness.'),'done','code',6,NULL,'2026-04-22 01:50:33','2026-04-22 01:50:33','2026-04-22 01:50:33','{"chief_sdk_tests":17,"hn_briefer_tests":9,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/40","sdk_version":"0.3.0","shim_removed":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:27:18','2026-04-22 01:50:33');
INSERT INTO tasks VALUES('t-proto-fs2','p-gtte',NULL,0,'Prototype: Chief FS CAS + FUSE shim (Rust)','Hypothesis: blake3 CAS store + FUSE shim at /chief/ that presents legacy paths as pinned aliases. Capture daemon on fanotify writes. Files: prototypes/chief-fs/{Cargo.toml,src/main.rs,src/cas.rs,src/fuse_shim.rs,src/capture_daemon.rs,README.md,measurements.md}. Acceptance: ''ls ~/Downloads'' returns aliased CIDs; delete keeps CAS blob; rename updates graph edge not CID; capture daemon p99 < 10ms per write. Worktree: proto/chief-fs. References: adr-0006, docs/research/2026-04-21-agent-native-fs.md. NOT on critical path for v0 — deferred after agent runtime lands.','done','code',5,'codex-proto-fs','2026-04-22 02:19:34','2026-04-22 02:19:36','2026-04-22 02:35:32','{"capture_p99_ms":2.85,"cas_p99_ms":1.32,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/47"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:19:36',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:32:10','2026-04-22 02:35:32');
INSERT INTO tasks VALUES('t-w6-sdk-ts','p-gtte',NULL,0,'Phase 1b: chief-sdk-ts 0.2 — TypeScript parity with Rust agent runtime surface',unistr('Phase 1 codex (PR #36) shipped Rust only. This task adds the TypeScript parallel bindings.\u000a\u000aDeliverables:\u000a1. packages/chief-sdk-ts/src/tier.ts — Tier literal union ''fast'' | ''deep''.\u000a2. packages/chief-sdk-ts/src/capability.ts — add ''llm.ai'', ''llm.harness'' to CapabilityKind literal. Keep ''llm.generate'' with JSDoc @deprecated marker.\u000a3. packages/chief-sdk-ts/src/ai.ts — AiBuilder class with prompt/input/schema/tier/maxTokens/call/stream.\u000a4. packages/chief-sdk-ts/src/harness.ts — HarnessBuilder + HarnessTranscript/Turn/Role types.\u000a5. packages/chief-sdk-ts/src/tool_handle.ts — opaque type via unique-symbol brand.\u000a6. packages/chief-sdk-ts/src/errors.ts — AiError, HarnessError.\u000a7. packages/chief-sdk-ts/tests/ — vitest mirroring Rust test matrix.\u000a8. packages/chief-sdk-ts/package.json — bump to 0.2.0.\u000a9. README updated.\u000a\u000aScope: packages/chief-sdk-ts/** only. NEVER touch crates/**, packages/chief-ui-ts/**, prototypes/**, docs/**.\u000a\u000aAcceptance:\u000a- npm --prefix packages/chief-sdk-ts run build clean.\u000a- npm --prefix packages/chief-sdk-ts test passes.\u000a- Types match Rust shape 1:1.\u000a- Shadow the Rust deprecation discipline: ''llm.generate'' stays as shim.\u000a- No internal Radix/Shadcn/Tauri re-exports (not that this pkg has them; just sanity check).\u000a\u000aNot blocking Phase 2/3 (Rust-only concerns). Useful for future TS-based packs.'),'cancelled','code',7,'codex-harness','2026-04-22 01:40:28','2026-04-22 01:40:28',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 01:40:28',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:44:46','2026-04-22 01:42:28');
INSERT INTO tasks VALUES('t-w6-custom-engine','p-gtte',NULL,0,'Agent Runtime Phase 3a: CustomEngine — in-tree Rust fallback for HarnessEngine (ADR-0014)',unistr('Per ADR-0014, CustomEngine must ship at v0 as a fallback (not deferred).\u000aMinimal ~300-LOC Rust implementation of the HarnessEngine trait that calls chief-inference directly with a strict tool-calling protocol: model emits JSON { type: ''tool_call'' | ''final'', ... }; we parse, broker-check, dispatch, feed back, loop.\u000aDeliverables:\u000a1. crates/chief-core/src/harness/engines/custom_engine.rs — HarnessEngine impl.\u000a2. Tool-calling prompt template that works with Qwen 2.5 (our local default).\u000a3. Tests: runs happy-path multi-turn, budget kill, external-action block.\u000a4. Opencode vs CustomEngine parity tests (same transcript against both given same mocked model).\u000aScope: crates/chief-core/**. Does NOT touch chief-sdk or chief-ui.\u000aBlocks on: t-w6-sdk-runtime.\u000aThis parallels t-w6-harness (OpencodeEngine adapter); ideally both ship in the same PR so the engine-switch can be tested end-to-end.'),'cancelled','code',9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:57:37','2026-04-22 01:17:59');
INSERT INTO tasks VALUES('t-w6-nixos-ci','p-gtte',NULL,0,'Dev Ops: NixOS VM CI — run eBPF/nspawn/Wayland acceptance tests from day 1',unistr('Per review feedback + ADR-0011 Linux-only concerns: set up a NixOS VM GitHub Action (or equivalent CI) that boots the NixOS flake and runs all acceptance tests that depend on Linux-only primitives.\u000a\u000aTests that MUST run on NixOS CI (not macOS):\u000a- eBPF fs/net cap enforcement (per docs/06-security-model.md)\u000a- systemd-nspawn sandbox boundaries\u000a- Wayland layer-shell rendering of the Brief\u000a- Firecracker microVM spawn (v1+; placeholder at v0)\u000a- FUSE + CAS-FS shim integration (when chief-fs lands)\u000a- Any harness test that depends on the real Linux capability model\u000a\u000aDeliverables:\u000a1. .github/workflows/nixos-ci.yml — uses nixos-shell / QEMU to boot the flake\u000a2. A pinned test harness that marks each test as ''nixos-only'' | ''both'' | ''mac-only''\u000a3. docs/contributing.md addition (new file) explaining which tests run where\u000a4. First passing run of current repo test matrix on NixOS CI\u000a\u000aScope: .github/workflows/**, new docs/contributing.md. Does NOT touch code.\u000aNot blocking Phase 2/3 — but MUST land before any Phase 3 acceptance claim.'),'done','shell',7,'codex-nixos-ci','2026-04-22 01:21:19','2026-04-22 01:26:54','2026-04-22 01:26:54','{"matrix":["nixos-only","both","mac-only"],"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/38","runner":"ubuntu-latest-with-linux-headers","summary":"Implemented provisional NixOS-equivalent CI pipeline with workflow, test matrix docs, and minimal flake"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 01:21:19',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:57:37','2026-04-22 01:26:54');
INSERT INTO tasks VALUES('t-w6-ts-lint','p-gtte',NULL,0,'Tooling: chief-ts-lint — build-time import scanner for TS packs (ADR-0011 enforcement)',unistr('Per review feedback: the ''Nix-flake build pipeline blocks non-whitelisted imports'' claim in docs/18-ui-standardization.md is not self-executing. Ship a real tool.\u000a\u000aApproach: minimal Rust or TS utility that parses TS pack sources and rejects top-level imports not on the allowlist.\u000a\u000aAllowlist: @chief-os/sdk, @chief-os/ui, pack-local relative imports, a small list of well-known utility packages (serde, zod, date-fns — TBD).\u000a\u000aBanned: direct @radix-ui/*, shadcn/*, tauri, react-dom internals, arbitrary web-font URLs, any @chief-os/ui-internal path.\u000a\u000aDeliverables:\u000a1. tools/chief-ts-lint/ (Rust binary via swc or ts-morph) or packages/chief-ts-lint/ (Node CLI)\u000a2. Integration into pack-build toolchain (Nix flake or simple CI step)\u000a3. Test fixtures: known-good pack (HN briefer TS analogue) + known-bad pack\u000a4. CI workflow addition\u000a\u000aScope: tools/** or packages/chief-ts-lint/**. Does NOT touch chief-sdk, chief-ui, or packs themselves.\u000aMust land before any third-party TS pack or first TS dogfood.'),'done','code',6,NULL,'2026-04-22 02:33:37','2026-04-22 02:33:37','2026-04-22 02:33:37','{"fixtures":4,"parser":"swc_core","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/46"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 00:57:37','2026-04-22 02:33:37');
INSERT INTO tasks VALUES('t-w6-sdk-ts2','p-gtte',NULL,0,'Phase 1b redo: chief-sdk-ts 0.2 — TypeScript parity with Rust agent runtime surface','Re-queued after codex-harness''s stale claim was cancelled (auto-claim via done --next then exit). See earlier t-w6-sdk-ts description: add Tier literal union, CapabilityKind llm.ai/llm.harness, AiBuilder/HarnessBuilder TS classes, opaque ToolHandle brand type, vitest tests mirroring Rust matrix. Scope: packages/chief-sdk-ts/** only. Bump to 0.2.0. See chief-sdk Rust impl (PR #36) for the 1:1 shape.','done','code',7,'codex-sdk-ts','2026-04-22 02:10:11','2026-04-22 02:10:13','2026-04-22 02:26:54','{"merged":true,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/45"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:10:13',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 01:42:28','2026-04-22 02:26:54');
INSERT INTO tasks VALUES('t-w5-file-brief','p-gtte',NULL,0,'Wave 5b: File-watcher briefer pack (second dogfood)','Second dogfood pack. Proves SDK scales beyond HN briefer''s net.http-centric shape by using fs.watch / fs.read / llm.ai instead. See /tmp/chief-os-file-watcher-brief.md for spec.','done','code',8,'codex-file-watcher','2026-04-22 02:09:00','2026-04-22 02:09:03','2026-04-22 02:17:15','{"grants":5,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/42"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:09:03',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:06:12','2026-04-22 02:17:15');
INSERT INTO tasks VALUES('t-h-tools','p-gtte',NULL,0,'Hardening: real ToolDispatcher — fs.*, net.http, mem.* (replaces EchoToolDispatcher stub)',unistr('Replace EchoToolDispatcher stub (in crates/chief-core/src/harness/runtime.rs) with real ToolDispatcher impl that actually executes fs.read / fs.write / net.http / mem.read / mem.write / surface.pane / notify.inbox calls.\u000aEach capability kind → real handler: fs.* via std::fs gated by grant paths; net.http via reqwest gated by grant hosts; mem.* via chief-mem (SQLite + vec) if landed, else in-memory graph stub; surface.pane emits events to the Brief; notify.inbox pushes to HAX Inbox backend.\u000aScope: crates/chief-core/**. Waits on oauth-wire (file-scope overlap).\u000aTests: real filesystem sandbox + real HTTP mock server + memory graph roundtrip + scope denial paths. Must also exercise Broker.check denying wrong hosts/paths/types.'),'cancelled','code',10,'codex-hyprland','2026-04-22 02:22:43','2026-04-22 02:22:43',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:22:43',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:15:47','2026-04-22 02:26:58');
INSERT INTO tasks VALUES('t-h-kernel-principal','p-gtte',NULL,0,'Hardening: kernel principal identity + boot attestation (ADR-0016 impl)',unistr('Implement ADR-0016: urn:chief:device:<pubkey> holds meta.root_of_trust; urn:chief:kernel receives grants at every boot via signed boot-attestation. First-run Ceremony binds device identity to user.\u000aScope: crates/chief-core/src/kernel_principal/ (new) + integration with broker (new CapabilityKind::MetaRootOfTrust already in sdk).\u000aTests: boot replay produces expected kernel grants; revoke-kernel-grant surfaces a ''Reset Chief'' ceremony link instead of actually revoking; meta.root_of_trust cannot be requested by any pack.'),'done','code',9,'codex-kernel-principal','2026-04-22 02:33:45','2026-04-22 02:33:55','2026-04-22 02:54:22','{"adr":"0016","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/50","tests":5}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:33:55',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:15:47','2026-04-22 02:54:22');
INSERT INTO tasks VALUES('t-h-hyprland','p-gtte',NULL,0,'Hardening: package Hyprland + chief-compositor.nix blur preset (ADR-0015 impl)',unistr('Per ADR-0015: bundle Hyprland as the Chief OS shipping Wayland compositor with a pinned version + chief-compositor.nix module with blur preset matching brand/visual-language.md §6.\u000aScope: flake.nix + new nix/chief-compositor.nix module. No code changes to any crate. Disables Hyprland tiling UX per ADR (single-surface-at-a-time).\u000aAcceptance: nix flake check passes; nixos-vm-test can boot the compositor; blur matches reference screenshots within visual tolerance.'),'done','shell',7,'codex-hyprland','2026-04-22 02:19:29','2026-04-22 02:19:29','2026-04-22 02:22:43','{"hyprland_rev":"v0.49.0","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/44","summary":"Hyprland v0.49.0 pinned in flake; chief-compositor.nix module implements blur/animation/keybind management per ADR-0015. Spring→bezier approximations documented."}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:19:29',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:15:47','2026-04-22 02:22:43');
INSERT INTO tasks VALUES('t-h-ebpf-proto','p-gtte',NULL,0,'Hardening: eBPF fs + net cap enforcement prototype (Linux defense-in-depth)',unistr('Per docs/06-security-model.md: ''eBPF enforces fs + net caps even if nspawn/namespace is misconfigured''. Build the prototype.\u000aScope: prototypes/chief-ebpf/ (new). Rust + libbpf-rs or aya. One .bpf.c program that denies file opens outside an allowlist + net connects outside allowed hosts.\u000aTests: nixos-only. Smoke test with two busy-box processes: one inside the policy, one attempting bypass; verify bypass is killed with EPERM.'),'done','code',6,'claude-ebpf','2026-04-22 03:29:01','2026-04-22 03:29:10','2026-04-22 03:39:03','{"hooks":["file_open","__sys_connect"],"loader":"aya","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/57"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:29:10',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:15:47','2026-04-22 03:39:03');
INSERT INTO tasks VALUES('t-h-firecracker-spike','p-gtte',NULL,0,'Hardening: Firecracker microVM evaluation spike (v1 planning)',unistr('NOT implementation — evaluation spike per ADR-0014 v1+ deferral. Measure Firecracker boot time for a Chief-pack microVM on reference hardware; document findings in docs/research/.\u000aScope: docs/research/YYYY-MM-DD-firecracker-spike.md. Maybe a small harness in prototypes/fc-spike/. Do NOT wire into chief-core; this informs v1+ not v0.\u000aAcceptance: reported boot time ± variance + recommended cold-boot-vs-snapshot strategy for v1+ sequencing.'),'done','research',3,'claude-firecracker','2026-04-22 03:30:13','2026-04-22 03:34:28','2026-04-22 03:34:28','{"cold_boot_ms":null,"cold_boot_ms_cited":"200-500ms (NSDI 2020, Kata benchmarks)","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/56","prototype_built":false,"prototype_skip_reason":"dev host macOS/arm64, no KVM","recommendation":"proceed","snapshot_restore_ms_cited":"5-20ms"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:30:13',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:15:47','2026-04-22 03:34:28');
INSERT INTO tasks VALUES('t-h-nspawn','p-gtte',NULL,0,'Hardening: systemd-nspawn sandbox for pack and engine processes (Linux deploy)',unistr('Implement the systemd-nspawn wrapper for (a) opencode engine subprocess, (b) pack agent processes on Linux/NixOS deploy. Per ADR-0002 + ADR-0014. macOS dev runs unsandboxed per explicit v0 concession; NixOS CI exercises real nspawn.\u000aScope: crates/chief-core/src/sandbox/ (new) + flake.nix updates.\u000aTests: nspawn-gated acceptance that fails if sandboxed process reaches outside declared FS/net namespace. Mark nixos-only.'),'done','code',9,'claude-nspawn','2026-04-22 03:10:53','2026-04-22 03:11:29','2026-04-22 03:16:44','{"linux":true,"macos":"passthrough","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/51"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:11:29',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:16:12','2026-04-22 03:16:44');
INSERT INTO tasks VALUES('t-h-opencode-real','p-gtte',NULL,0,'Hardening: real opencode subprocess binary integration (not HTTP stub)',unistr('Per ADR-0014: v0 OpencodeEngine uses httpmock stub; this wires the REAL opencode binary as a child subprocess supervised by chief-core (under systemd-nspawn on Linux).\u000aScope: crates/chief-core/src/harness/engines/opencode.rs + opencode_supervisor.rs. NixOS flake: add opencode + nodejs_20 runtime deps.\u000aTests: live subprocess spawn-connect-tool-call-kill cycle. Mark nixos-only.'),'done','code',8,'claude-opencode','2026-04-22 03:28:17','2026-04-22 03:28:23','2026-04-22 03:39:03','{"mock_preserved":true,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/58","tests":108}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:28:23',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:16:12','2026-04-22 03:39:03');
INSERT INTO tasks VALUES('t-h-provider-wire','p-gtte',NULL,0,'Hardening: wire Models surface config → ChiefCoreAiBackend provider dispatch',unistr('When user binds a cloud provider via Controls → Models UI, ChiefCoreAiBackend routes Cloud-tier calls through that provider using chief-oauth sealed storage for API keys.\u000aScope: crates/chief-core/src/router/picker.rs + harness/backend.rs — extend ModelChoice::Cloud dispatch.\u000aTests: end-to-end with OpenRouter via ModelChoice::Cloud path. Gated behind OPENROUTER_API_KEY + #[ignore].'),'done','code',8,'claude-provider-wire','2026-04-22 03:11:39','2026-04-22 03:11:41','2026-04-22 03:24:23','{"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/54","real":["openrouter"],"stubbed":["anthropic","openai"],"tests":99}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:11:41',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:16:12','2026-04-22 03:24:23');
INSERT INTO tasks VALUES('t-h-hn-real','p-gtte',NULL,0,'Hardening: HN briefer real network integration (replace stubs with real HN/Substack)',unistr('After t-h-tools lands, HN briefer''s integration test can hit real news.ycombinator.com + Substack. Replace stub paths in tests with #[ignore]-gated live test.\u000aScope: prototypes/hn-briefer/tests/**.\u000aTests: live HN top stories fetched, scored via ctx.ai(), Card emitted with real data. Mark #[ignore].'),'done','code',7,'claude-hn-real','2026-04-22 03:12:44','2026-04-22 03:12:50','2026-04-22 03:24:23','{"live_tests":3,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/53"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:12:50',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:16:12','2026-04-22 03:24:23');
INSERT INTO tasks VALUES('t-h-sdk-fs-ctx','p-gtte',NULL,0,'SDK gap: add ctx.fs() accessor to chief-sdk CapabilityContext (blocks real file-watcher dispatch)',unistr('Codex file-watcher briefer (PR #42) flagged: SDK exposes fs.watch + fs.read CapabilityKind variants but no corresponding ctx.fs() accessor method on CapabilityContext. File-watcher pack stubbed file discovery via ctx.ai() prompt hack instead of real fs access.\u000aScope: crates/chief-sdk/src/context.rs — add ctx.fs().watch(paths), ctx.fs().read(path), ctx.fs().list(dir). Matching InMemoryFsConnector stub. Wire to real dispatcher via h-tools task.\u000aScope bound: crates/chief-sdk/** + packages/chief-sdk-ts/** (TS parity). Does NOT touch chief-core (that''s h-tools scope).\u000aTests: ctx.fs() accessor returns handle; InMemoryFsConnector smoke tests.\u000aAfter this lands, file-watcher briefer''s stub hack should be replaced with real ctx.fs() calls in a follow-up.'),'done','code',7,'claude-sdk-fs','2026-04-22 03:13:20','2026-04-22 03:13:23','2026-04-22 03:21:04','{"parity":true,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/52","rust_tests":"30 passed (15 unit + 8 new fs_ctx + 7 sdk_contract)","sdk_version":"0.3.1","ts_tests":"15 passed (5 basic + 10 new fs)"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:13:23',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:20:27','2026-04-22 03:21:04');
INSERT INTO tasks VALUES('t-h-tools2','p-gtte',NULL,0,'Hardening: real ToolDispatcher — fs.*, net.http, mem.* (replaces EchoToolDispatcher stub)',unistr('Replace EchoToolDispatcher stub (crates/chief-core/src/harness/runtime.rs) with real ToolDispatcher impl that actually executes fs.read / fs.write / net.http / mem.read / mem.write / surface.pane / notify.inbox calls.\u000a\u000aEach capability kind → real handler: fs.* via std::fs gated by grant paths; net.http via reqwest gated by grant hosts; mem.* via chief-mem (SQLite + vec) if landed, else in-memory graph stub; surface.pane emits events to the Brief; notify.inbox pushes to HAX Inbox backend.\u000a\u000aScope: crates/chief-core/**. Previous claim on t-h-tools was orphaned (agent process ended); this replaces it. oauth-wire is merged (PR #43), no blockers.'),'done','code',10,'codex-h-tools','2026-04-22 02:33:45','2026-04-22 02:33:55','2026-04-22 02:46:35','{"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/49","real":["fs.read","fs.write","net.http"],"stubbed":["mem","surface","notify","fs.watch"]}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:33:55',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:27:13','2026-04-22 02:46:35');
INSERT INTO tasks VALUES('t-demo-backend','p-gtte',NULL,0,'Demo backend — chief-core HTTP API for Brief/Inbox/Omnibar/Ceremony/Trust surfaces',unistr('Extend crates/chief-core/src/routes.rs with the routes the React shell needs: GET /v1/brief (richer than current /brief with needs + handled + trust ledger), GET /v1/inbox, GET /v1/inbox/stream (SSE for live updates), POST /v1/omnibar/search (search memory+events+inbox), GET /v1/ceremony/{id}, POST /v1/ceremony/{id}/approve (hold-confirmed), POST /v1/ceremony/{id}/deny, GET /v1/trust-ledger, GET /v1/models. Plus static bundle serving at / and /assets/*.\u000a\u000aScope: crates/chief-core/src/routes.rs, crates/chief-core/src/routes/ (new module split if needed), crates/chief-core/tests/demo_api.rs (new). Preserve backwards compat on existing routes.'),'done','code',10,'claude-demo-backend','2026-04-22 03:54:05','2026-04-22 03:54:07','2026-04-22 04:07:30','{"binary":"chief_core_server (port 8080 default)","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/59","routes":["/v1/brief","/v1/inbox","/v1/inbox/stream","/v1/omnibar/search","/v1/ceremony","/v1/ceremony/{id}","/v1/ceremony/{id}/approve","/v1/ceremony/{id}/deny","/v1/trust-ledger","/v1/models","/","/assets/*"],"tests":"129 existing + 15 new integration tests, all pass"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:54:07',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 03:52:19','2026-04-22 04:07:30');
INSERT INTO tasks VALUES('t-demo-frontend','p-gtte',NULL,0,'Demo frontend — full React shell with Brief + Inbox + Omnibar + Ceremony',unistr('Evolve prototypes/morning-brief/ (React) into the full shell: Brief surface enhanced to hit /v1/brief live, HAX Inbox drawer wired to /v1/inbox/stream via EventSource, Omnibar floating palette (Cmd+Space) hitting /v1/omnibar/search, Ceremony modal with hold-to-confirm ring hitting /v1/ceremony/{id}/approve. All surfaces share the same App shell with global keybinds (Cmd+I inbox, Cmd+Space omnibar, Esc dismiss).\u000a\u000aScope: prototypes/morning-brief/src/ only (may add new subdirs for new surfaces). Must build via ''npm run build'' cleanly. No Tauri changes — web-only for demo.'),'done','code',10,'claude-demo-frontend','2026-04-22 03:54:56','2026-04-22 03:54:59','2026-04-22 04:13:43','{"bundle_gz":"90KB","pr":"https://github.com/santoshkumarradha/ChiefOS/pull/60","surfaces":["Brief","Inbox","Omnibar","Ceremony"],"tests":33}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:54:59',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 03:52:19','2026-04-22 04:13:43');
INSERT INTO tasks VALUES('t-demo-runner','p-gtte',NULL,0,'Demo packaging — Dockerfile + docker-compose + demo-seed + README',unistr('Create deploy/docker/ with: Dockerfile (multi-stage: builds chief-core binary + npm-build React bundle, final layer ubuntu:24.04 slim), docker-compose.yml for one-command demo, demo-runner binary in crates/chief-core/src/bin/demo_run.rs that starts chief-core HTTP API + launches HN briefer pack ONCE immediately on boot (so Brief has real AI-generated content within ~30s) + schedules it for re-run every 15 min, + launches file-watcher briefer pack watching /workspace volume.\u000a\u000aZERO mock data. All demo content must come from real agent activity:\u000a- HN briefer runs against real OpenRouter, real HN API, real Substack RSS → real NEEDS YOU cards\u000a- file-watcher briefer → real file events from /workspace volume\u000a- Ceremony flows arise from REAL capability escalations (e.g. pack tries net.http to a domain not in its grant → broker denies → emits ceremony-pending event). Demo-run seeds the grant-escalation scenario by launching the HN briefer with a NARROW net.http grant (only news.ycombinator.com) so it hits an escalation when trying substack.com — this is a real architectural demo, not a mock\u000a\u000aREADME.md ''Run the demo'' section with docker run command requiring OPENROUTER_API_KEY env var (do NOT bake a key into image).\u000a\u000aScope: deploy/docker/ (new), crates/chief-core/src/bin/demo_run.rs (new), README.md top section only. Must pass: docker build succeeds, docker run with OPENROUTER_API_KEY env var exposes http://localhost:8080 with real agent-generated content.'),'done','code',9,'claude-demo-runner','2026-04-22 03:58:13','2026-04-22 03:58:16','2026-04-22 04:13:43','{"docker_image_mb":166,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/61","verified_live":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 03:58:16',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 03:52:19','2026-04-22 04:13:43');
