INSERT INTO plandb_meta VALUES('current_project','p-gtte');
INSERT INTO task_notes VALUES('n-ar3i','t-h-sdk-fs-ctx',NULL,'discovery: pre-existing ts type error in context.ts (object literals where string union expected). Fixing in-scope since context.ts is in task''s file list and it''s blocking the npm run build gate.','2026-04-22 03:18:16');
INSERT INTO learnings VALUES('c-kny6','p-gtte',NULL,'default','pattern','Pre-commit hook test: verifying auto-export works end-to-end.','2026-04-21 21:35:57');
INSERT INTO learnings VALUES('c-m9b4','p-gtte',NULL,'default','discovery','proto/events completed: Signed Typed Event Log with Merkle chain. Implemented ADR-0005 substrate: 7 event kinds, fjall storage, Ed25519 signing, chain verification with tampering detection. Concurrent safety tested. Benchmark: ~900 events/sec single-threaded. PR #10 opened. Ready for integration into chief-kernel.','2026-04-21 21:38:01');
INSERT INTO learnings VALUES('c-1y56','p-gtte','t-chief-core-contracts','codex-chief-core','discovery','chief-core integration notes: prototypes expose NullHarness async API, chief_mem::ChiefMem sync SQLite store, chief_event_log_proto::EventLog with CapabilityCheck/ToolCall/UIAction events, chief_region_router_proto deterministic classify(), and chief_inference Attestor/EphemeralDeviceKey/verify primitives. chief-inference InferenceRouter is lower-level; chief-core can build a small stub inference adapter that calls LocalLlamaCppStub and signs CanonicalPrompt/CanonicalOutput with Attestor. Prototype gap: ChiefMem has no public tombstone method, so chief-core should maintain queue/card state and can add its own small SQLite metadata store under runtime/ for reversible queue state.','2026-04-21 22:03:01');
INSERT INTO learnings VALUES('c-0tg1','p-gtte',NULL,'default','discovery','Docker validation: 4 bugs found in original Dockerfile/compose: (1) placeholder SHA256 for Qwen model would fail on first build — real sha256 is 626b4a6678b86442240e33df819e00132d3ba7dddfe1cdc4fbb18e0a9615c62d (from HF Hub x-linked-etag); (2) Rust 1.82 base image too old — rmp 0.8.15 requires edition2024 (Rust 1.85+) — bumped to rust:1.89-slim-bookworm; (3) chief-core defaults to --bind 127.0.0.1:4711 which isn''t reachable from host port-mapping — wrap in entrypoint.sh that execs with --bind 0.0.0.0:4711; (4) no static-file server for Morning Brief on port 5173 — Dockerfile copied dist to /app/morning-brief but nothing served it — added busybox-static and run busybox httpd on :5173 from entrypoint. Also: Docker Desktop''s default IPv6 port mapping ''::]:5173->5173'' hijacks localhost-over-v6 since busybox httpd is IPv4-only; pin host side to ''0.0.0.0:PORT:PORT'' in compose to force IPv4-only host mapping. Fixed demo-docker.sh payload key (prompt -> text) to match routes.rs. Validation results: build ~200s cold, image 4.35GB, boot-to-healthy ~7s, memory 3MB (stub backend), all 4 endpoints pass.','2026-04-21 22:27:09');
INSERT INTO learnings VALUES('c-fwic','p-gtte','t-proto-fs','default','discovery','t-mb-live-api complete: Morning Brief now polls chief-core /brief every 3s. Approval flow working (POST /approve) with offline graceful degradation. All 6 API endpoints wrapped with typed fetch + timeouts (5s default, 30s for /intent & /approve). Tests: api.test.ts (6 endpoints + errors) + useBriefState.test.tsx (polling, offline fallback, backoff reset). PR#26.','2026-04-21 22:28:45');
INSERT INTO learnings VALUES('c-7gtg','p-gtte','t-proto-fs','default','discovery','HN Briefer dogfood: SDK surface was complete. No gaps found. Badge enum is properly closed. Grant validation works. InMemoryConnector stubs sufficient for integration testing.','2026-04-22 00:20:06');
INSERT INTO learnings VALUES('c-igv0','p-gtte',NULL,'default','discovery','ADR-0013 Phase 1 work started: implementing agent runtime SDK surface. Codex delegation attempted but implementing directly with manual precision. Scope: add Tier enum, CapabilityKind extensions (LlmAi, LlmHarness), ToolHandle, AiBuilder, HarnessBuilder types + traits + stubs + tests. HN briefer deprecation shim critical.','2026-04-22 00:37:43');
INSERT INTO learnings VALUES('c-8hr0','p-gtte',NULL,'default','discovery','SDK gaps discovered: fs.watch/fs.read grants defined in CapabilityKind but no direct ctx.fs() accessor yet. Stub via ctx.ai() call works as workaround. Grant shape accurate for both manifest.toml TOML format and Rust Grant::new() builder.','2026-04-22 02:17:19');
INSERT INTO learnings VALUES('c-xuq7','p-gtte',NULL,'default','discovery','SDK TypeScript parity 0.3.0: Implemented Tier (fast|deep), CapabilityKind (37 variants + llm.ai/harness/meta.prompt/meta.root_of_trust), AiBuilder fluent API, HarnessBuilder with transcript, ToolHandle opaque type (branded), error discriminated unions (AiError/HarnessError), CapabilityContext methods (ai/harness/netTool/memoryTool/fsTool/aiTool/harnessTool), full public exports from index.ts. Build clean (tsc strict mode), tests pass (vitest 5 tests). Version 0.3.0. Ready for commit.','2026-04-22 02:22:35');
INSERT INTO learnings VALUES('c-mmdz','p-gtte','t-h-hyprland','codex-hyprland','decision','ADR-0015 impl: Hyprland v0.49.0 pinned; spring→bezier translation used because Hyprland lacks native spring easing. Approximations documented in chief-compositor.nix.','2026-04-22 02:22:39');
INSERT INTO learnings VALUES('c-v6jv','p-gtte','t-h-nspawn','claude-nspawn','discovery','discovery: systemd-nspawn --bind-ro/--bind syntax uses SRC[:DEST[:OPTS]]; we use SRC:SRC so in-sandbox paths mirror host paths 1:1 - makes policy authoring trivial and keeps --chdir working','2026-04-22 03:15:35');
INSERT INTO learnings VALUES('c-zalc','p-gtte','t-h-nspawn','claude-nspawn','discovery','discovery: nspawn inherits host netns when neither --private-network nor --network-veth is given; NetworkPolicy::HostShared therefore emits NO flag (documented via comment in build_nspawn_args)','2026-04-22 03:15:35');
INSERT INTO learnings VALUES('c-div4','p-gtte','t-h-nspawn','claude-nspawn','decision','decision: NetworkPolicy::Private variant is defined now but downgrades to HostShared behavior with tracing::warn! at v0 since userland proxy does not exist yet - keeps call sites stable across v0->v1 transition','2026-04-22 03:15:35');
INSERT INTO learnings VALUES('c-aodp','p-gtte',NULL,'default','discovery','discovery: packages/chief-sdk-ts/src/context.ts has a pre-existing type error on main — it constructs CapabilityKind as object literals but the type is a string union. The TS ''build'' acceptance gate on t-h-sdk-fs-ctx is blocked until this is fixed. I will fix context.ts in-scope (task allows editing this file) by reducing object literals to string kinds. Deeper discriminated-union rework belongs in a follow-up task to bring TS CapabilityKind to parity with Rust. This does not change the public API of ctx.fsTool/ctx.netTool/etc (those only get used with string paths).','2026-04-22 03:18:13');
INSERT INTO learnings VALUES('c-shdh','p-gtte','t-h-hn-real','claude-hn-real','discovery','discovery: ctx.ai() in chief-sdk hardcodes InMemoryAiBackend (src/context.rs line 61). Real-model scoring via ctx.ai() from packs isn''t wired up yet; live tests for hn-briefer call OpenRouter directly via reqwest to prove the model/prompt path, and run the full on_tick with a real reqwest NetworkConnector for the fetch side. Follow-up needed: SDK backend-injection point to let packs opt into ChiefCoreAiBackend.','2026-04-22 03:20:32');
INSERT INTO learnings VALUES('c-9bbl','p-gtte','t-h-hn-real','claude-hn-real','discovery','discovery: ctx.ai() hardcodes InMemoryAiBackend in chief-sdk src/context.rs; live tests call OpenRouter directly via reqwest to cover the real-model path. every.to/feed is 404; switched to astralcodexten.substack.com/feed.','2026-04-22 03:20:38');
INSERT INTO learnings VALUES('c-s7u2','p-gtte',NULL,'default','discovery','discovery: ChiefCoreAiBackend''s legacy pick() path requires ModelsConfig.providers map to be populated for Cloud bindings. resolve_cloud_route() bypasses this so the ProviderRegistry from the Models surface becomes the single source of truth for cloud providers. Legacy path still works for backward compat.','2026-04-22 03:21:18');
INSERT INTO learnings VALUES('c-m09m','p-gtte',NULL,'default','discovery','ChiefCoreAiBackend''s legacy pick() path requires ModelsConfig.providers map populated for Cloud bindings. resolve_cloud_route() bypasses this so ProviderRegistry from Models surface is single source of truth.','2026-04-22 03:21:21');
INSERT INTO learnings VALUES('c-492w','p-gtte',NULL,'default','discovery','FTS restore verified v2','2026-04-22 03:27:05');
INSERT INTO learnings VALUES('c-rafm','p-gtte','t-followup-primitives','claude-primitives','discovery','Clipboard Pane has no ADR yet despite being flagged substrate-spine in primitive-rethink research; added a note in docs/05-surfaces.md that a follow-up ADR is warranted. Also caught stale FAISS references in docs/03-chief-kernel.md (Memory Graph row, storage-layout tree, open-questions item 2) — all rewritten to sqlite-vec/iroh-blobs per ADR-0008.','2026-04-22 03:32:51');
INSERT INTO learnings VALUES('c-450b','p-gtte','t-h-firecracker-spike','claude-firecracker','discovery','firecracker spike: dev host is macOS/arm64 (no KVM). Cited NSDI 2020 + upstream + Kata benchmarks: ~125ms cold-boot, ~5ms snapshot-restore, ~5MB RSS overhead. Recommendation: proceed to prototype in v1, default to snapshot-restore. vsock is the right transport for broker<->pack. Prototype skipped; follow-up task needed to measure on Linux+KVM before v1 branch lands.','2026-04-22 03:33:37');
INSERT INTO learnings VALUES('c-lc6p','p-gtte','t-h-ebpf-proto','claude-ebpf','discovery','chief-ebpf: chose aya 0.13 over libbpf-rs — pure Rust, no C toolchain, cleaner on NixOS. aya is cfg-gated target_os=linux only, macOS gets a no-op stub. eBPF program source in src/ebpf/chief_enforce.rs is gated by #[cfg(target_arch = "bpf")] so it is invisible to userland builds; dedicated bpf-linker CI step builds it separately. Hooks: file_open LSM (fs) + __sys_connect kprobe (net). v1 will upgrade connect to socket_connect LSM. Linux integration tests are #[ignore] + cfg(target_os=linux) since they need CAP_BPF + bpf artefact.','2026-04-22 03:35:16');
INSERT INTO learnings VALUES('c-mdnd','p-gtte','t-demo-backend','claude-demo-backend','discovery','demo-backend discovery: kept hax-inbox prototype unchanged — the /v1 API uses an in-memory InboxStore directly in chief-core because (a) the prototype is sqlite-backed and we didn''t want contention with the broker db, (b) the API only needs chronological list+broadcast, no persistence.','2026-04-22 04:05:37');
INSERT INTO learnings VALUES('c-hcqv','p-gtte','t-demo-backend','claude-demo-backend','discovery','demo-backend discovery: GrantHandle in chief-core::broker does not derive Deserialize, which forced CeremonyItem to drop Deserialize too. If a future task needs to read CeremonyItems from JSON (e.g. restore), add #[derive(Deserialize)] to GrantHandle first.','2026-04-22 04:05:45');
INSERT INTO learnings VALUES('c-4gs4','p-gtte','t-demo-backend','claude-demo-backend','decision','demo-backend design: trust ledger uses ''first path segment of source_agent'' as the category (e.g. ''hn-briefer'' -> ''hn''). Crude but predictable. Refine when the real capability taxonomy binds categories to capabilities.','2026-04-22 04:05:45');
